//! `Z/ext/standard/html_tables.h` at the pinned tag, as data: the
//! single-byte charsets' maps to and from Unicode, the HTML 5 and HTML
//! 4.01 entity tables in both directions, and the basic entities.
//! php generates the header from `html_tables/html_table_gen.php`; the
//! rows here are its rows, transcribed, in the order `html.c` walks
//! them, and the `get_html_translation_table` witnesses beside `html`
//! hold every row of them to the oracle.

/// One code point's row of an `entity_stage3_row` table: the entity,
/// or, where a second code point may follow (`ambiguous`), the entity
/// for none and each `(second, entity)` of its `multicodepoint_table`.
pub(super) enum Row {
    One(&'static str),
    Many(Option<&'static str>, &'static [(u32, &'static str)]),
}

use Row::{Many, One};

/// `stage3_table_be_noapos_00000`: the basic entities of HTML 4.01,
/// where `'` has no name.
pub(super) static ENCODE_BASIC_NOAPOS: &[(u32, Row)] = &[
    (0x22, One("quot")),
    (0x26, One("amp")),
    (0x27, One("#039")),
    (0x3C, One("lt")),
    (0x3E, One("gt")),
];

/// `stage3_table_be_apos_00000`: the basic entities of every other
/// document type.
pub(super) static ENCODE_BASIC_APOS: &[(u32, Row)] = &[
    (0x22, One("quot")),
    (0x26, One("amp")),
    (0x27, One("apos")),
    (0x3C, One("lt")),
    (0x3E, One("gt")),
];

/// `ent_ht_be_noapos`, sorted by name.
pub(super) static DECODE_BASIC_NOAPOS: &[(&str, u32, u32)] = &[
    ("#039", 0x27, 0),
    ("amp", 0x26, 0),
    ("gt", 0x3E, 0),
    ("lt", 0x3C, 0),
    ("quot", 0x22, 0),
];

/// `ent_ht_be_apos`, sorted by name.
pub(super) static DECODE_BASIC_APOS: &[(&str, u32, u32)] = &[
    ("amp", 0x26, 0),
    ("apos", 0x27, 0),
    ("gt", 0x3E, 0),
    ("lt", 0x3C, 0),
    ("quot", 0x22, 0),
];

